    if (!std::strcmp(name, "at")) { at = v; return; }
    if (!std::strcmp(name, "n0")) { n0 = v; return; }
    if (!std::strcmp(name, "g0")) { g0 = v; return; }
    if (!std::strcmp(name, "t0")) { t0 = v; return; }
    if (!std::strcmp(name, "n1")) { n1 = v; return; }
